# Let's analyze the input/output pairs manually first
inputs = ['gwbvwc', 'evuj', 'afvzw', 'xyxh', 'ujwezv']
outputs = ['gwbvwd', 'evuj', 'wfvjbvzw', 'xdgwh', 'ujwezv']

print("Input strings:")
for i, inp in enumerate(inputs):
    print(f"  {i}: '{inp}'")

print("\nOutput strings:")
for i, out in enumerate(outputs):
    print(f"  {i}: '{out}'")

print("\nDifferences:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    if inp != out:
        print(f"  {i}: '{inp}' -> '{out}'")
    else:
        print(f"  {i}: '{inp}' -> '{out}' (unchanged)")

